#!/usr/bin/env node
/**
 * Writes docs/aval/SPECIALIST_CATALOGUE_REVIEW.md: the model-drafted
 * Specialist catalogue, separated into routing metadata, capability
 * definitions, operational guidance and legal/compliance claims, with every
 * item that needs a qualified reviewer flagged. Generated from
 * lib/agents/organization/review.ts; do not edit by hand.
 *
 *   node scripts/specialist-catalogue-review.mjs
 */
import { writeFileSync } from "node:fs";
import { LEADS, SPECIALISTS, specialistsForDomain } from "../lib/agents/organization/index.ts";
import { FIELD_KIND, reviewSpecialist } from "../lib/agents/organization/review.ts";

const reviews = SPECIALISTS.map((specialist) => ({ specialist, review: reviewSpecialist(specialist) }));
const areas = new Map();
for (const { specialist, review } of reviews) for (const row of review.legalReview) areas.set(row.area, [...new Set([...(areas.get(row.area) ?? []), specialist.id])]);
const kinds = Object.entries(FIELD_KIND).reduce((all, [field, kind]) => ({ ...all, [kind]: [...(all[kind] ?? []), `\`${field}\``] }), {});

const lines = [
  "# Specialist catalogue review",
  "",
  "Generated by `scripts/specialist-catalogue-review.mjs`. Do not edit by hand.",
  "",
  "The 266 Specialist definitions were drafted with model assistance and checked by validators and tests. **None of it has been reviewed by a property-management professional or by counsel.** It is operational guidance and product definition, never legal policy.",
  "",
  "## What each field is",
  "",
  `- **Routing metadata**, which only decides where work goes: ${kinds.routing.join(", ")}. A mistake here causes a misroute, never an unauthorized action.`,
  `- **Capability definitions**, where code enforces the product's behavior (tools, checks), not the text: ${kinds.capability.join(", ")}.`,
  `- **Operational guidance**, which briefs a model and is enforced by nothing: ${kinds.guidance.join(", ")}.`,
  `- **Legal / compliance claims**, which must be reviewed and never relied on as policy: ${kinds.legal.join(", ")}, plus any text below flagged as regulated.`,
  "",
  "**Where authority lives.** What may actually happen is decided by the deterministic layer, not by this catalogue:",
  "",
  "- permissions (`lib/agents/permissions.ts`, `lib/agents/organization`)",
  "- approval and financial policy (`lib/agents/policy.ts`, `execution-policy.ts`)",
  "- the PMS capability matrix and mandatory human checkpoints (`lib/pms`)",
  "- the workspace's operating profile",
  "",
  "Every Specialist and Lead is briefed with that statement.",
  "",
  "## Needs legal or compliance review, by area",
  "",
  `${reviews.filter(({ review }) => review.legalReview.length).length} of ${SPECIALISTS.length} Specialists touch regulated ground. Review them for each jurisdiction the workspace operates in:`,
  "",
  ...[...areas.entries()].sort((a, b) => b[1].length - a[1].length).map(([area, ids]) => `- **${area}** (${ids.length}): ${ids.map((id) => `\`${id}\``).join(", ")}`),
  "",
  "## Every Specialist needs domain review",
  "",
  "Each row below lists the regulated areas its text touches and the words that flagged it. A row with none still needs a property-management professional to confirm its boundary, forbidden actions and completion contract.",
  "",
];
for (const lead of LEADS) {
  lines.push(`### ${lead.name}`, "", "| Specialist | Regulated areas (field: matched words) |", "|---|---|");
  for (const specialist of specialistsForDomain(lead.domain)) {
    const review = reviewSpecialist(specialist);
    lines.push(`| ${specialist.name} | ${review.legalReview.map((row) => `${row.area} (${row.field}: "${row.match}")`).join("; ") || "none flagged; domain review only"} |`);
  }
  lines.push("");
}
writeFileSync(new URL("../docs/aval/SPECIALIST_CATALOGUE_REVIEW.md", import.meta.url), lines.join("\n") + "\n");
console.log({ flagged: reviews.filter(({ review }) => review.legalReview.length).length, areas: Object.fromEntries([...areas].map(([area, ids]) => [area, ids.length])) });
